import sys,json
p=sys.stdin.read().split('\n===SEP===\n')
me=json.loads(p[0]) if p[0].strip() else {}
d=json.loads(p[1]) if len(p)>1 and p[1].strip() else {}
iss=d
f=iss.get('fields') or {}
a=(f.get('assignee') or {}).get('accountId')
st=f.get('status') or {}
cat=(st.get('statusCategory') or {}).get('key')
errs=[]
if a != me.get('accountId'):
    errs.append('assignee=%s' % a)
if cat != 'indeterminate':
    errs.append('statut=%s (categorie %s)' % (st.get('name'), cat))
if errs:
    sys.stderr.write('Etat final inattendu : ' + ', '.join(errs) + '\n')
    sys.exit(1)
sys.stdout.write(json.dumps({'key': iss.get('key'), 'status': st.get('name'), 'ok': True}))
